PACKAGE BODY p AS
  PROCEDURE sweep(n NUMBER) IS
    i NUMBER := 0;
  BEGIN
    FOR r IN (SELECT id FROM sweep_queue) LOOP
      DELETE FROM sweep_items WHERE id = r.id;
    END LOOP;
    WHILE i < n LOOP
      i := i + 1;
    end loop;
    <<outer>>
    LOOP
      EXIT outer WHEN i > n;
      i := i + 1;
    END LOOP outer;
  END sweep;
  FUNCTION total RETURN NUMBER IS
    t NUMBER;
  BEGIN
    SELECT SUM(amount) INTO t FROM ledger;
    RETURN t;
  END total;
END p;

