PACKAGE BODY p AS
  FUNCTION grade(score NUMBER) RETURN VARCHAR2 IS
    label VARCHAR2(10) := CASE WHEN score IS NULL THEN 'none' END;
  BEGIN
    CASE
      WHEN score >= 90 THEN label := 'A';
      WHEN score >= 80 THEN label := 'B';
      ELSE label := 'C';
    END CASE;
    SELECT CASE WHEN COUNT(*) > 0 THEN label ELSE 'none' END INTO label FROM grades WHERE grade = label;
    RETURN CASE label WHEN 'A' THEN 'top' ELSE label END;
  END grade;
  PROCEDURE repeat_log(n NUMBER) IS
  BEGIN
    FOR i IN 1 .. CASE WHEN n > 0 THEN n ELSE 1 END LOOP
      INSERT INTO repeat_log_tab VALUES (i);
    END LOOP;
    UPDATE repeat_done SET flag = 1;
  END repeat_log;
  PROCEDURE after_case IS
  BEGIN
    DELETE FROM after_case_tab;
  END after_case;
END p;

